const data={"new": "data:image/png;base64,", "old": "data:image/png;base64,", "normal": "data:image/png;base64,", "base1": "data:image/png;base64,", "base7": "data:image/png;base64,"},img={};for(const k in data){img[k]=new Image;img[k].src=data[k]};let time=0,last=performance.now(),step=0,playing=true;const durations=[8,10,8,10];function current(t){let v=t*60/1000%36;for(let i=0;i<4;i++){if(v<durations[i])return i;v-=durations[i]}return 0}document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Reprendre';last=performance.now()};document.querySelector('#next').onclick=()=>{playing=false;step=(step+1)%4;document.querySelector('#play').textContent='Reprendre'};function draw(now){if(playing){time+=now-last;step=current(time)}last=now;let dir=+document.querySelector('#dir').value;document.querySelector('#num').textContent='Image '+(step+1)+' / 4';document.querySelector('#orig').style.display=dir===1||dir===7?'block':'none';if(dir===1||dir===7)document.querySelector('#base').src=data['base'+dir];for(const k of ['normal','old','new']){let c=document.querySelector('#'+k).getContext('2d');c.clearRect(0,0,400,300);c.fillStyle='rgba(25,43,29,.24)';c.beginPath();c.ellipse(200,260,47,8,0,0,2*Math.PI);c.fill();c.imageSmoothingEnabled=false;let w=k==='new'?64:32,h=k==='new'?112:56;if(img[k].complete&&img[k].naturalWidth)c.drawImage(img[k],step*w,dir*h,w,h,120,0,160,280)}requestAnimationFrame(draw)}requestAnimationFrame(draw)